import {premises,machines,strategies as plans,calculate} from './model.js';
const $=id=>document.getElementById(id),money=n=>'Sh '+n.toLocaleString('en-US'),num=n=>n.toLocaleString('en-US',{maximumFractionDigits:3});
let drop=20;
const fields=[['milk','Milk purchased (tons)',1,'any'],['production','Production (whole units)',0,1],['requested','Requested sales (10,000 blocks)',0,10000],['allocation','Possible actual allocation',0,10000],['market','Market investment (Sh)',1000,1],['borrow','New borrowing (Sh)',0,1],['term','Loan term (seasons)',1,1]];
$('strategies').innerHTML=plans.map((s,i)=>`<article class="plan"><div class="plan-heading"><span class="letter">${i?'B':'A'}</span><h3>${s.name}</h3></div><div class="plan-fields"><label>Machine to purchase<select data-i="${i}" data-k="machine" aria-label="Strategy ${i?'B':'A'} machine">${Object.entries(machines).map(([k,m])=>`<option value="${k}" ${+k===s.machine?'selected':''}>Machine ${k} · ${num(m.capacity)} capacity</option>`).join('')}</select></label><label>One rented premise<select data-i="${i}" data-k="premises" aria-label="Strategy ${i?'B':'A'} premise">${Object.entries(premises).map(([k,p])=>`<option ${k===s.premises?'selected':''} value="${k}">${k} · ${money(p.rent)} rent</option>`).join('')}</select></label>${fields.map(([k,l,min,step])=>`<label>${l}<input required aria-label="Strategy ${i?'B':'A'} ${l}" type="number" min="${min}" step="${step}" ${k==='term'?'max="8"':k==='borrow'?'max="200000"':''} data-i="${i}" data-k="${k}" value="${s[k]}"></label>`).join('')}</div><div id="result${i}"></div></article>`).join('');
const rows=[['produced','Production','Locked before the market','units'],['eligible','Eligible request','min(request, production), rounded down to 10,000','units'],['sales','Actual sales','Trainer allocation, not demand forecast','units'],['spoilage','Unsold ice cream','produced − sold; no recovery','units'],['unusedMilk','Unused milk (tons)','purchased − produced / 20,000','units'],['revenue','Revenue','sold × Sh 2','total'],['milkCost','Milk cost','entire milk purchase × Sh 20,000'],['maintenance','Maintenance','all owned machines, including idle'],['depreciation','Depreciation','purchase price / 8 seasons'],['gross','Gross profit','revenue − milk − maintenance − depreciation','total'],['transport','Transport','sold × premise rate'],['market','Market investment','paid even if sales are zero'],['bonus','Staff bonus','5% of positive gross profit'],['salary','Fixed salaries','Sh 10,000 every season'],['rent','Rent','one selected premise'],['interest','Interest','10% of debt before repayment'],['pbt','Profit before tax','gross − transport − market − bonus − salaries − rent − interest','total'],['tax','Game tax','10% of positive profit; opening loss pool is zero'],['pool','Closing tax-loss pool','current loss; no cash refund'],['net','Net profit','profit before tax − tax','total'],['purchase','Machine purchase','cash only; no purchase expense'],['borrow','Loan received','cash only; not revenue'],['principal','First principal repayment','loan / term, due this season'],['debt','Closing loan principal','loan − first principal repayment'],['book','Closing machine book value','purchase − depreciation'],['life','Remaining machine life (seasons)','8 − first season','units'],['afterPurchase','Cash after machine payment','100,000 + borrowing − purchase'],['afterMilk','Cash after milk payment','previous cash − milk'],['afterMarket','Cash after market payment','previous cash − market; all advances now paid'],['operating','Cash operating costs','milk + maintenance + transport + market + bonus + salaries + rent'],['cashFlow','Net cash flow','net profit + depreciation − purchase + loan − principal','total'],['closing','Closing cash','100,000 + cash flow','total']];
function status(r){const issues=[['machine advance',r.afterPurchase],['milk advance',r.afterMilk],['market advance',r.afterMarket],['season end',r.closing]].filter(x=>x[1]<0);return `<div class="status ${issues.length?'bad':''}">${issues.length?issues.map(([l,v])=>`${l}: ${money(-v)} funding gap`).join('; '):'All advance payments and season-end cash are funded.'}</div>`;}
function result(r){return `<div class="results"><div><small>Net profit</small><strong>${money(r.net)}</strong></div><div><small>Closing cash</small><strong>${money(r.closing)}</strong></div></div>${status(r)}`;}
function render(){
 const rs=plans.map(s=>calculate(s));
 rs.forEach((r,i)=>{$('result'+i).innerHTML=r.errors.length?`<div class="status bad">${r.errors.join('<br>')}</div>`:result(r);});
 if(rs.some(r=>r.errors.length)||!$('stress').checkValidity()){for(const id of ['financials','differences','downside'])$(id).innerHTML='';$('recommendation').innerHTML='<h2>Correct the highlighted inputs</h2><p>The comparison is paused until the decisions meet the official Winter rules.</p>';return;}
 const ranked=rs.map((r,i)=>({r,i})).filter(x=>x.r.minimum>=0).sort((x,y)=>y.r.net-x.r.net),best=ranked[0];
 const tied=ranked.length===2&&ranked[0].r.net===ranked[1].r.net;
 $('recommendation').innerHTML=`<div class="eyebrow">OFFICIAL YEAR 1 WINTER · CONDITIONAL RECOMMENDATION</div><h2>${!best?'Neither plan is funded':tied?'The plans tie on net profit':`Prefer ${plans[best.i].name}`}</h2><p>${best?`Expected net profit ${money(best.r.net)}; lowest modelled cash ${money(best.r.minimum)}.`:'Reduce commitments or arrange a compliant loan before locking decisions.'} <b>Most important assumption:</b> the trainer allocates the entered sales volume. The Sh 1,000 minimum investment does not guarantee rank or sales. Choose for cumulative net profit, not closing cash alone.</p>`;
 $('financials').innerHTML=`<thead><tr><th>Posted calculation</th><th>A · Low-cost entry</th><th>B · Capacity with discipline</th><th>B − A</th></tr></thead><tbody>${rows.map(([k,l,f,t])=>`<tr class="${t==='total'?'total':''}"><td>${l}<small>${f}</small></td>${[rs[0][k],rs[1][k],rs[1][k]-rs[0][k]].map(v=>`<td class="${v<0?'negative':''}">${t==='units'?num(v):money(v)}</td>`).join('')}</tr>`).join('')}</tbody>`;
 const d=k=>money(rs[1][k]-rs[0][k]);
 $('differences').innerHTML=[['Sales and spoilage',`B − A revenue: ${d('revenue')}. Unsold units: A ${num(rs[0].spoilage)}, B ${num(rs[1].spoilage)}. Milk is expensed once, including waste.`],['Premises and transport',`B − A rent: ${d('rent')}; transport: ${d('transport')}. At 60,000 sales D costs Sh 23,000 for rent plus transport, compared with Sh 27,000 at E and Sh 34,000 at B.`],['Machine and milk commitments',`B − A machine purchase: ${d('purchase')}; maintenance: ${d('maintenance')}; depreciation: ${d('depreciation')}; milk: ${d('milkCost')}. Purchase reduces cash; depreciation reduces gross profit.`],['Market, salaries and financing',`B − A market spend: ${d('market')}; bonus: ${d('bonus')}; interest: ${d('interest')}. Both pay Sh 10,000 fixed salaries. Borrowing must include funding for its first repayment and interest this season.`],['Profit and cash',`B − A net profit: ${d('net')}; closing cash: ${d('closing')}. A new machine has seven seasons left after Winter. The prior pilot loss and cash never enter these accounts.`],['Why start with 60,000?',`Machine 1 can produce 72,000, but sales requests use 10,000-unit blocks. A 60,000-unit plan needs three tons of milk. At the minimum market spend it leaves Sh 4,000 after advances without borrowing. A 70,000 plan needs at least Sh 6,000 borrowing before any season-end payments.`]].map(([h,p])=>`<p><b>${h}</b>${p}</p>`).join('');
 const low=plans.map(s=>calculate(s,drop));
 const winner=low.map((r,i)=>({r,i})).filter(x=>x.r.minimum>=0).sort((x,y)=>y.r.net-x.r.net)[0];
 $('downside').innerHTML=low.map((r,i)=>`<article class="plan"><h3>${i?'B':'A'} · ${plans[i].name}</h3><p>${num(r.sales)} sold · ${num(r.spoilage)} unsold<br>Net-profit change: ${money(r.net-rs[i].net)}</p>${result(r)}</article>`).join('')+`<p>${winner?`Under this downside, ${plans[winner.i].name} has the highest funded net profit (${money(winner.r.net)}).`:'Neither downside plan is funded.'} This is an allocation stress test, not a prediction of the trainer’s decision.</p>`;
}
 document.addEventListener('input',e=>{const el=e.target;if(el.id==='stress'){drop=el.valueAsNumber;render();return;}if(el.dataset.i===undefined)return;plans[+el.dataset.i][el.dataset.k]=el.dataset.k==='premises'?el.value:el.value===''?NaN:Number(el.value);render();});
 render();
 if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_strategy_comparison',description:'Read official Year 1 Winter strategy results and validation errors.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected empty object');return plans.map(s=>({name:s.name,...calculate(s)}));}})).catch(()=>{});}catch{}}

